{"cards": [{"node_code": "N_5a6c8e86e80b9176", "definition": "研究工业机器人在物料搬运、机床上下料及堆垛码放场景中的系统配置、路径优化及与物流设备的集成应用。", "boundary": "聚焦于离散物料或整件工件的位移、抓取与放置任务。边界在于强调物流效率、节拍匹配及与传送带、AGV或立体库的接口，不涉及改变工件物理形态的加工工艺或精密装配。", "includes": ["机床自动上下料系统、托盘码垛与拆垛工作站", "重载搬运机器人及与输送线、立体仓库的集成方案", "基于视觉或力控的无序抓取与柔性搬运技术"], "excludes": ["涉及焊接、切割或磨削等改变工件形态的加工工艺", "精密零部件的组装、紧固或质量检测任务"], "sibling_distinctions": [{"other_code": "N_2d1560e50d710d17", "rule": "本节点关注物料位置改变（搬运/码垛），兄弟节点关注工件物理属性改变（焊接/喷涂/加工）。"}, {"other_code": "N_89fc44fdc3acadf0", "rule": "本节点关注单一或简单序列的物流任务，兄弟节点关注多工序协同、精密装配及在线检测的复杂工作站。"}], "cross_boundary_rule": ""}, {"node_code": "N_2d1560e50d710d17", "definition": "研究工业机器人在焊接、喷涂、切割及磨削等工艺场景中的系统集成、工艺参数匹配及专用末端执行器应用。", "boundary": "聚焦于通过机器人执行改变工件物理或化学状态的加工过程。边界在于强调工艺质量（如焊缝成型、漆膜均匀性）与机器人运动的耦合，不涉及单纯的物料位移或精密装配。", "includes": ["弧焊、激光焊、点焊等焊接机器人工作站", "汽车车身或大型结构件的自动喷涂系统", "激光切割、打磨抛光及去毛刺等加工机器人应用"], "excludes": ["不涉及能量输入或材料去除的纯搬运与码垛任务", "以功能验证或尺寸测量为主的检测与装配任务"], "sibling_distinctions": [{"other_code": "N_5a6c8e86e80b9176", "rule": "本节点关注工艺执行（焊接/喷涂），兄弟节点关注物流执行（搬运/码垛）。"}, {"other_code": "N_89fc44fdc3acadf0", "rule": "本节点关注单一或连续的加工工艺，兄弟节点关注多部件组装、检测及柔性制造单元。"}], "cross_boundary_rule": ""}, {"node_code": "N_89fc44fdc3acadf0", "definition": "研究工业机器人在精密装配、在线检测及柔性制造单元中的系统集成，涵盖多机器人协同、力控装配及视觉引导检测。", "boundary": "聚焦于高复杂度、高柔性或高精度要求的任务，强调机器人对工件姿态、力/力矩的精细控制及多源信息融合。边界在于区别于单一重复性工艺，强调适应性、检测精度及多工序集成。", "includes": ["精密电子、汽车零部件的自动装配与紧固工作站", "基于机器视觉或传感器的在线质量检测与分拣系统", "多机器人协同作业及柔性制造单元（FMC）集成方案"], "excludes": ["大批量、低精度的简单搬运或单一焊接/喷涂工艺", "不涉及机器人本体或仅关注纯软件算法的通用检测理论"], "sibling_distinctions": [{"other_code": "N_5a6c8e86e80b9176", "rule": "本节点强调精密、柔性及检测功能，兄弟节点强调物流效率与简单位移。"}, {"other_code": "N_2d1560e50d710d17", "rule": "本节点强调装配集成与检测反馈，兄弟节点强调单一加工工艺的执行与质量。"}], "cross_boundary_rule": ""}]}
